-- US credentials per job, verified against official pages on 2026-11-27.
with s(k,url,pub) as (values ('faa-amt','https://www.faa.gov/mechanics/become','Federal Aviation Administration'),('fcc-grol','https://www.fcc.gov/types-licenses','Federal Communications Commission'),('osha-crane','https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1427','Occupational Safety and Health Administration'),('nccco-rigger','https://www.onetonline.org/link/certinfo/8741-B','O*NET OnLine (certification details)'),('fra-240','https://www.ecfr.gov/current/title-49/subtitle-B/chapter-II/part-240','Electronic Code of Federal Regulations'),('fra-242','https://www.ecfr.gov/current/title-49/subtitle-B/chapter-II/part-242','Electronic Code of Federal Regulations'),('uscg-mmc','https://www.ecfr.gov/current/title-46/chapter-I/subchapter-B/part-11/subpart-E','Electronic Code of Federal Regulations'),('twic','https://www.dco.uscg.mil/nmc/twic/','U.S. Coast Guard National Maritime Center'),('state-electrician','https://www.bls.gov/ooh/construction-and-extraction/electricians.htm','U.S. Bureau of Labor Statistics, Occupational Outlook Handbook'),('state-plumber','https://www.bls.gov/ooh/construction-and-extraction/plumbers-pipefitters-and-steamfitters.htm','U.S. Bureau of Labor Statistics, Occupational Outlook Handbook'),('inspector-cert','https://www.bls.gov/ooh/construction-and-extraction/construction-and-building-inspectors.htm','U.S. Bureau of Labor Statistics, Occupational Outlook Handbook'),('adci-card','https://www.onetonline.org/link/certinfo/11852-A','O*NET OnLine (certification details)'),('gwo-bst','https://www.globalwindsafety.org/standards/basic-safety-training-standard','Global Wind Organisation'),('ase-t','https://ase.com/tests/t1-t8/','National Institute for Automotive Service Excellence'),('cdl','https://www.bls.gov/ooh/installation-maintenance-and-repair/line-installers-and-repairers.htm','U.S. Bureau of Labor Statistics, Occupational Outlook Handbook'),('boiler-license','https://www.bls.gov/ooh/production/stationary-engineers-and-boiler-operators.htm','U.S. Bureau of Labor Statistics, Occupational Outlook Handbook'),('elevator-license','https://www.bls.gov/ooh/construction-and-extraction/elevator-installers-and-repairers.htm','U.S. Bureau of Labor Statistics, Occupational Outlook Handbook'),('naec-cet','https://www.onetonline.org/link/certinfo/6056-A','O*NET OnLine (certification details)'),('nims-machining','https://www.bls.gov/ooh/production/machinists-and-tool-and-die-makers.htm','U.S. Bureau of Labor Statistics, Occupational Outlook Handbook')),
si as (insert into public.sources(url,publisher,title,retrieved_at) select url,pub,'Credential requirements ('||k||')','2026-11-27' from s returning id,title),
c(k,name,kind,issuer,info) as (values ('faa-amt','{"en": "FAA Mechanic Certificate (Airframe and/or Powerplant)"}'::jsonb,'license','Federal Aviation Administration (FAA)','https://www.faa.gov/mechanics/become'),('fcc-grol','{"en": "FCC General Radiotelephone Operator License (GROL)"}'::jsonb,'license','Federal Communications Commission (FCC)','https://www.fcc.gov/types-licenses'),('osha-crane','{"en": "Crane operator certification"}'::jsonb,'certificate','Accredited testing organization (for example NCCCO), an audited employer program, or a state or local license','https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.1427'),('nccco-rigger','{"en": "NCCCO Rigger Level I and II"}'::jsonb,'certificate','National Commission for the Certification of Crane Operators (NCCCO)','https://www.nccco.org/nccco/certifications/rigger'),('fra-240','{"en": "Locomotive engineer certification (FRA, 49 CFR Part 240)"}'::jsonb,'license','Your railroad, under Federal Railroad Administration rules','https://www.ecfr.gov/current/title-49/subtitle-B/chapter-II/part-240'),('fra-242','{"en": "Conductor certification (FRA, 49 CFR Part 242)"}'::jsonb,'license','Your railroad, under Federal Railroad Administration rules','https://www.ecfr.gov/current/title-49/subtitle-B/chapter-II/part-242'),('uscg-mmc','{"en": "Merchant Mariner Credential with engineer endorsement"}'::jsonb,'license','U.S. Coast Guard National Maritime Center','https://www.ecfr.gov/current/title-46/chapter-I/subchapter-B/part-11/subpart-E'),('twic','{"en": "Transportation Worker Identification Credential (TWIC)"}'::jsonb,'registration','Transportation Security Administration (TSA)','https://www.dco.uscg.mil/nmc/twic/'),('state-electrician','{"en": "State electrician license (journeyman)"}'::jsonb,'license','Your state licensing board','https://www.bls.gov/ooh/construction-and-extraction/electricians.htm'),('state-plumber','{"en": "State or local plumbing license"}'::jsonb,'license','Your state or city licensing board','https://www.bls.gov/ooh/construction-and-extraction/plumbers-pipefitters-and-steamfitters.htm'),('inspector-cert','{"en": "State inspector license or ICC certification"}'::jsonb,'certificate','Your state, or the International Code Council (ICC)','https://www.iccsafe.org/professional-development/certification/'),('adci-card','{"en": "ADCI commercial diver certification card"}'::jsonb,'certificate','Association of Diving Contractors International (ADCI)','https://www.adc-int.org/certifications'),('gwo-bst','{"en": "GWO Basic Safety Training"}'::jsonb,'certificate','Global Wind Organisation (GWO) certified training providers','https://www.globalwindsafety.org/standards/basic-safety-training-standard'),('ase-t','{"en": "ASE Medium-Heavy Truck certification (T1 to T8)"}'::jsonb,'certificate','National Institute for Automotive Service Excellence (ASE)','https://ase.com/tests/t1-t8/'),('cdl','{"en": "Commercial driver''s license (CDL)"}'::jsonb,'license','Your state, under FMCSA standards','https://www.fmcsa.dot.gov/registration/commercial-drivers-license/drivers'),('boiler-license','{"en": "State or city boiler operator / stationary engineer license"}'::jsonb,'license','Your state or city','https://www.bls.gov/ooh/production/stationary-engineers-and-boiler-operators.htm'),('elevator-license','{"en": "State elevator mechanic license"}'::jsonb,'license','Your state','https://www.bls.gov/ooh/construction-and-extraction/elevator-installers-and-repairers.htm'),('naec-cet','{"en": "Certified Elevator Technician (CET)"}'::jsonb,'certificate','National Association of Elevator Contractors (NAEC)','https://www.onetonline.org/link/certinfo/6056-A'),('nims-machining','{"en": "NIMS Machining Level I credentials"}'::jsonb,'certificate','National Institute for Metalworking Skills (NIMS)','https://www.nims-skills.org/faq/220')),
ci as (insert into public.credentials(country_code,name,kind,issuer,info_url,source_id,as_of)
  select 'US',c.name,c.kind,c.issuer,c.info,si.id,'2026-11-27' from c join si on si.title='Credential requirements ('||c.k||')' returning id,source_id),
cm as (select c.k, ci.id cid, ci.source_id sid from ci join si on si.id=ci.source_id join c on si.title='Credential requirements ('||c.k||')'),
r(k,slug,mand,detail) as (values ('faa-amt','aircraft-mechanic',true,'{"note_en": "Needed to approve aircraft for return to service. You must be 18+, read, write and speak English, and have 18 months of experience for one rating (30 months for both) or graduate from an FAA-certificated mechanic school. Then pass written, oral and practical tests within 24 months."}'::jsonb),('fcc-grol','avionics-technician',false,'{"note_en": "Needed to adjust, maintain or internally repair FCC-licensed aircraft radio transmitters. Technicians working on communications equipment may need it."}'::jsonb),('osha-crane','crane-operator',true,'{"note_en": "OSHA requires construction crane operators to be certified by equipment type (or type and capacity). An accredited certificate is portable between employers and lasts 5 years. Your employer must also evaluate you and pays for the certification."}'::jsonb),('nccco-rigger','rigger',false,'{"note_en": "OSHA requires rigging on crane jobs to be done by a qualified rigger but does not require a third-party card. Many employers ask for NCCCO Rigger I; Level I is required before Level II."}'::jsonb),('fra-240','locomotive-engineer',true,'{"note_en": "Every railroad must run a written program that trains and certifies its locomotive engineers. You are usually hired as a trainee and certified by the railroad."}'::jsonb),('fra-242','railroad-conductor',true,'{"note_en": "Only people who meet federal safety standards may serve as conductors. Railroads train and certify new conductors through their own approved program."}'::jsonb),('uscg-mmc','ship-engineer',true,'{"note_en": "Licensed engineers hold an engineer officer endorsement (for example Third Assistant Engineer, up to Chief Engineer). Entry-level engine crew start with a QMED rating."}'::jsonb),('twic','ship-engineer',true,'{"note_en": "Required for all mariners holding Coast Guard credentials. Not having one can be grounds to deny your mariner credential."}'::jsonb),('state-electrician','electrician',true,'{"note_en": "Most states require electricians to pass a test and be licensed. The usual path is a 4- or 5-year paid apprenticeship with about 2,000 hours of on-the-job training a year, after which you are a journey worker."}'::jsonb),('state-plumber','plumber',true,'{"note_en": "Most states and some cities require plumbers to be licensed. It usually takes 2 to 5 years of experience before you can work independently."}'::jsonb),('inspector-cert','construction-inspector',true,'{"note_en": "Most states and cities require a license or certification. Some run their own exams; others require certification from a professional body such as the ICC."}'::jsonb),('adci-card','commercial-diver',false,'{"note_en": "OSHA requires every dive team member to have the training or experience for the job. ADCI member companies require divers trained to ADCI standards, usually through a commercial diving school."}'::jsonb),('gwo-bst','wind-turbine-technician',false,'{"note_en": "The safety training wind companies agree on. Five modules: First Aid, Manual Handling, Fire Awareness, Working at Height and Sea Survival. Not a legal requirement, but employers commonly ask for it."}'::jsonb),('ase-t','diesel-mechanic',false,'{"note_en": "Voluntary. Covers Class 4 to 8 trucks. Certification needs 2 years of hands-on experience, and vocational training can count for up to half."}'::jsonb),('cdl','power-line-installer',false,'{"note_en": "Line workers who drive heavy vehicles usually need a state CDL. You pass a state knowledge test and a skills test."}'::jsonb),('boiler-license','boiler-operator',false,'{"note_en": "Required in some states and cities, usually in classes by equipment type and size. A license from one place may not transfer to another."}'::jsonb),('elevator-license','elevator-installer',true,'{"note_en": "Most states require a license. The main path in is the NEIEP union apprenticeship: an 18-week probationary course, then 4 years and 8,000 hours of paid on-the-job learning plus classes."}'::jsonb),('naec-cet','elevator-installer',false,'{"note_en": "An education and certification program built for the elevator industry, separate from the union apprenticeship."}'::jsonb),('nims-machining','tool-and-die-maker',false,'{"note_en": "Optional, but shows employers you can run machine tools to industry standards."}'::jsonb),('nims-machining','cnc-programmer',false,'{"note_en": "Optional, but shows employers you can set up and program machines to industry standards."}'::jsonb))
insert into public.occupation_requirements(occupation_id,country_code,kind,credential_id,mandatory,detail,source_id,as_of)
select o.id,'US','credential',cm.cid,r.mand,r.detail,cm.sid,'2026-11-27' from r join cm on cm.k=r.k join public.occupations o on o.slug=r.slug;
